// src/app/(dashboard)/dashboard/page.tsx
"use client";

import React, { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useCurrentUser } from "@/hooks/use-current-user";
import { api } from "@/lib/api";
import type { Lead, Tenant } from "@/types";

export default function DashboardPage() {
  const router = useRouter();
  const { currentUser, loading } = useCurrentUser();

  const [tenant, setTenant] = useState<Tenant | null>(null);
  const [leads, setLeads] = useState<Lead[]>([]);
  const [loadingLeads, setLoadingLeads] = useState(true);

  // 1) once we know who the user is, get his tenant
  useEffect(() => {
    if (loading) return;

    // not logged in → go login
    if (!currentUser) {
      router.push("/login");
      return;
    }

    // user exists → fetch tenant from Firestore
    (async () => {
      try {
        const t = await api.getTenant(currentUser.tenantId);
        if (!t) {
          // user created but tenant doc missing → send to setup
          router.push("/setup");
          return;
        }
        setTenant(t);

        // once we have tenant → load leads
        setLoadingLeads(true);
        const data = await api.getLeads(t.id);
        setLeads(data);
      } catch (err) {
        console.error("Dashboard init error:", err);
      } finally {
        setLoadingLeads(false);
      }
    })();
  }, [loading, currentUser, router]);

  // 2) global loading
  if (loading) {
    return <div className="p-6 text-slate-300">Checking your account…</div>;
  }

  // 3) still fetching tenant
  if (!currentUser) {
    return null;
  }

  if (!tenant) {
    // we already redirected to /setup above, but in case Next keeps rendering:
    return <div className="p-6 text-slate-300">Finishing your setup…</div>;
  }

  return (
    <div className="p-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-white">Dashboard</h1>
        <p className="text-slate-400 text-sm mt-1">
          Welcome back, {currentUser.name || "operator"} — here’s what’s happening today.
        </p>
      </div>

      {/* Top stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="rounded-2xl p-5 bg-slate-900/40 border border-slate-800">
          <div className="text-xs uppercase tracking-wide text-slate-400">
            Total Leads
          </div>
          <div className="text-3xl font-semibold text-white mt-2">
            {loadingLeads ? "…" : leads.length}
          </div>
          <div className="text-xs text-slate-500 mt-1">
            All time for {tenant.businessName || "your business"}
          </div>
        </div>

        <div className="rounded-2xl p-5 bg-slate-900/40 border border-slate-800">
          <div className="text-xs uppercase tracking-wide text-slate-400">
            This Week
          </div>
          <div className="text-3xl font-semibold text-white mt-2">
            {loadingLeads
              ? "…"
              : leads.filter((l) => {
                  if (!l.created) return false;
                  const d = new Date(l.created);
                  const now = new Date();
                  const diffDays =
                    (now.getTime() - d.getTime()) / (1000 * 60 * 60 * 24);
                  return diffDays <= 7;
                }).length}
          </div>
          <div className="text-xs text-slate-500 mt-1">
            New inbound leads
          </div>
        </div>

        <div className="rounded-2xl p-5 bg-slate-900/40 border border-slate-800">
          <div className="text-xs uppercase tracking-wide text-slate-400">
            Plan
          </div>
          <div className="text-xl font-semibold text-white mt-2">
            {tenant.planId ? tenant.planId.toUpperCase() : "No plan"}
          </div>
          <div className="text-xs text-slate-500 mt-1">
            Manage in Billing
          </div>
        </div>
      </div>

      {/* Recent leads list */}
      <div className="rounded-2xl bg-slate-900/30 border border-slate-800">
        <div className="flex items-center justify-between px-5 py-4 border-b border-slate-800/70">
          <div>
            <h2 className="text-sm font-semibold text-white">Recent leads</h2>
            <p className="text-xs text-slate-400 mt-1">
              Last 10 captured via forms / SMS / calls
            </p>
          </div>
          <button
            onClick={() => router.push("/leads")}
            className="text-xs px-3 py-1.5 rounded-md bg-slate-800 hover:bg-slate-700 text-white"
          >
            View all
          </button>
        </div>

        <div className="divide-y divide-slate-800/60">
          {loadingLeads ? (
            <div className="px-5 py-6 text-slate-400 text-sm">
              Loading leads…
            </div>
          ) : leads.length === 0 ? (
            <div className="px-5 py-6 text-slate-500 text-sm">
              No leads yet. Connect a form or create one manually.
            </div>
          ) : (
            leads.slice(0, 10).map((lead) => (
              <div
                key={lead.id}
                className="px-5 py-3 flex items-center justify-between gap-4"
              >
                <div>
                  <div className="text-sm text-white font-medium">
                    {lead.name || "Unknown lead"}
                  </div>
                  <div className="text-xs text-slate-400">
                    {/* you don’t have email on Lead, so just show phone */}
                    {lead.phone || "No contact provided"}
                  </div>
                </div>
                <div className="text-xs text-slate-500">
                  {lead.created || "—"}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}
